#!/usr/bin/env node
import {
  runPipeline
} from "./chunk-XW73TKNN.js";

// src/services/builder.ts
import pLimit from "p-limit";
import { basename } from "path";
async function buildFiles(files, opts = {}) {
  const limit = pLimit(20);
  const moduleCache = /* @__PURE__ */ new Map();
  return Promise.all(
    files.map(
      (file) => limit(async () => {
        const { compiled, analyzed, usedStock } = await runPipeline(file, {
          db: opts.db,
          scaleFactor: opts.scaleFactor,
          lang: opts.lang,
          paths: opts.paths,
          stock: opts.stock,
          moduleCache
        });
        return {
          slug: basename(file, ".gram"),
          file,
          data: analyzed ?? compiled,
          usedStock
        };
      })
    )
  );
}

export {
  buildFiles
};
